CREATE TABLE "ListingNote" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"listingId" TEXT NOT NULL,"content" VARCHAR(2000) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "ListingNote_pkey" PRIMARY KEY ("id"));
